/**
 * Postgres schema (Drizzle). Ids are text generated by the app (see ids.ts),
 * columns are snake_case, timestamps carry a time zone and chips are integers.
 *
 * Change this file, then generate a migration:
 *   npx drizzle-kit generate --config apps/server/drizzle.config.ts
 */

import { sql } from 'drizzle-orm';
import {
  bigint,
  bigserial,
  check,
  index,
  integer,
  jsonb,
  pgTable,
  primaryKey,
  text,
  timestamp,
  uniqueIndex,
  type AnyPgColumn,
} from 'drizzle-orm/pg-core';

const at = (name: string) => timestamp(name, { withTimezone: true, mode: 'date' });
const chips = (name: string) => bigint(name, { mode: 'number' });

/** SQL list for a check constraint, from a readonly tuple of string literals. */
function oneOf(values: readonly string[]) {
  return sql.raw(values.map((v) => `'${v}'`).join(', '));
}

export const TABLE_STATUSES = ['open', 'paused', 'stopped', 'archived'] as const;
export const TABLE_MODES = ['cash', 'tournament'] as const;
export const MOVEMENT_KINDS = [
  'buy-in',
  'rebuy',
  'add-on',
  'host-add',
  'host-remove',
  'host-set',
  'cash-out',
  'escrow-in',
  'escrow-out',
  'bounty',
  'rake',
] as const;
export const JOB_STATUSES = ['pending', 'running', 'done', 'failed', 'cancelled'] as const;
export const TOURNAMENT_STATUSES = ['registering', 'seating', 'running', 'paused', 'finished', 'cancelled'] as const;

export type TableStatus = (typeof TABLE_STATUSES)[number];
export type TableMode = (typeof TABLE_MODES)[number];
export type MovementKind = (typeof MOVEMENT_KINDS)[number];
export type JobStatus = (typeof JOB_STATUSES)[number];
export type TournamentStatus = (typeof TOURNAMENT_STATUSES)[number];

// ---------------------------------------------------------------- identity

/** A player is the public, stable id seen at tables. Guests get one per browser. */
export const players = pgTable(
  'players',
  {
    id: text('id').primaryKey(),
    /** Empty until the player picks a name. */
    displayName: text('display_name').notNull().default(''),
    createdAt: at('created_at').notNull().defaultNow(),
    lastSeenAt: at('last_seen_at').notNull().defaultNow(),
    accountId: text('account_id').references((): AnyPgColumn => accounts.id, { onDelete: 'set null' }),
  },
  (t) => [index('players_account_id_idx').on(t.accountId)],
);

/** Browser secrets, stored only as sha256 hashes. Each maps to one player. */
export const playerTokens = pgTable(
  'player_tokens',
  {
    tokenHash: text('token_hash').primaryKey(),
    playerId: text('player_id')
      .notNull()
      .references(() => players.id, { onDelete: 'cascade' }),
    createdAt: at('created_at').notNull().defaultNow(),
  },
  (t) => [index('player_tokens_player_id_idx').on(t.playerId)],
);

/** Username and password accounts. Usernames are unique ignoring case. */
export const accounts = pgTable(
  'accounts',
  {
    id: text('id').primaryKey(),
    /** As typed at sign-up; uniqueness is on lower(username). */
    username: text('username').notNull(),
    /** scrypt$N$r$p$salt$hash, see identity/password.ts. */
    passwordHash: text('password_hash').notNull(),
    /** The player id this account plays as; other linked guest ids keep their history. */
    primaryPlayerId: text('primary_player_id')
      .notNull()
      .references((): AnyPgColumn => players.id),
    createdAt: at('created_at').notNull().defaultNow(),
    /** A one-time password reset code from the admin, stored as a sha256 hash. Null when none is open. */
    resetCodeHash: text('reset_code_hash'),
    resetCodeExpiresAt: at('reset_code_expires_at'),
  },
  (t) => [uniqueIndex('accounts_username_lower_idx').on(sql`lower(${t.username})`)],
);

/** Logged-in sessions, so an account works across devices. */
export const sessions = pgTable(
  'sessions',
  {
    id: text('id').primaryKey(),
    accountId: text('account_id')
      .notNull()
      .references(() => accounts.id, { onDelete: 'cascade' }),
    tokenHash: text('token_hash').notNull(),
    createdAt: at('created_at').notNull().defaultNow(),
    expiresAt: at('expires_at').notNull(),
  },
  (t) => [
    uniqueIndex('sessions_token_hash_idx').on(t.tokenHash),
    index('sessions_account_id_idx').on(t.accountId),
  ],
);

// ---------------------------------------------------------------- tables

export const tables = pgTable(
  'tables',
  {
    id: text('id').primaryKey(),
    ownerPlayerId: text('owner_player_id')
      .notNull()
      .references(() => players.id),
    /** The runtime's typed settings (zod schema owned by the runtime). */
    settings: jsonb('settings').$type<unknown>().notNull(),
    settingsVersion: integer('settings_version').notNull().default(1),
    status: text('status', { enum: TABLE_STATUSES }).notNull().default('open'),
    mode: text('mode', { enum: TABLE_MODES }).notNull().default('cash'),
    tournamentId: text('tournament_id'),
    clubId: text('club_id'),
    createdAt: at('created_at').notNull().defaultNow(),
    lastActivityAt: at('last_activity_at').notNull().defaultNow(),
    archivedAt: at('archived_at'),
  },
  (t) => [
    index('tables_status_activity_idx').on(t.status, t.lastActivityAt),
    index('tables_owner_idx').on(t.ownerPlayerId),
    index('tables_tournament_idx').on(t.tournamentId),
    check('tables_status_check', sql`${t.status} in (${oneOf(TABLE_STATUSES)})`),
    check('tables_mode_check', sql`${t.mode} in (${oneOf(TABLE_MODES)})`),
  ],
);

/** The runtime's full JSON state, overwritten at every hand boundary. */
export const tableSnapshots = pgTable('table_snapshots', {
  tableId: text('table_id')
    .primaryKey()
    .references(() => tables.id, { onDelete: 'cascade' }),
  /** Snapshot format version, so a loader can migrate or refuse older shapes. */
  version: integer('version').notNull(),
  state: jsonb('state').$type<unknown>().notNull(),
  savedAt: at('saved_at').notNull().defaultNow(),
});

/** Who changed which settings, and from which hand the change applies. */
export const settingsChanges = pgTable(
  'settings_changes',
  {
    id: text('id').primaryKey(),
    tableId: text('table_id')
      .notNull()
      .references(() => tables.id, { onDelete: 'cascade' }),
    /** Null for changes made by the system (tournament director, scheduler). */
    actorPlayerId: text('actor_player_id').references(() => players.id),
    changes: jsonb('changes').$type<unknown>().notNull(),
    effectiveHand: integer('effective_hand').notNull(),
    createdAt: at('created_at').notNull().defaultNow(),
  },
  (t) => [index('settings_changes_table_idx').on(t.tableId, t.createdAt)],
);

/** One stretch of a player sitting in one seat. Open while ended_at is null. */
export const seatSessions = pgTable(
  'seat_sessions',
  {
    id: text('id').primaryKey(),
    tableId: text('table_id')
      .notNull()
      .references(() => tables.id),
    playerId: text('player_id')
      .notNull()
      .references(() => players.id),
    seat: integer('seat').notNull(),
    startedAt: at('started_at').notNull().defaultNow(),
    endedAt: at('ended_at'),
  },
  (t) => [
    index('seat_sessions_table_idx').on(t.tableId),
    uniqueIndex('seat_sessions_open_seat_idx').on(t.tableId, t.seat).where(sql`${t.endedAt} is null`),
    uniqueIndex('seat_sessions_open_player_idx').on(t.tableId, t.playerId).where(sql`${t.endedAt} is null`),
    check('seat_sessions_seat_check', sql`${t.seat} >= 0`),
  ],
);

/**
 * Append-only chip ledger (a trigger rejects UPDATE and DELETE). `amount` is
 * the signed change to the player's stack, so stack_after = stack_before +
 * amount. Rake rows describe chips leaving the table and need no player.
 */
export const chipMovements = pgTable(
  'chip_movements',
  {
    id: text('id').primaryKey(),
    /** Insertion order; created_at can tie within a millisecond. */
    seq: bigint('seq', { mode: 'number' }).generatedAlwaysAsIdentity(),
    tableId: text('table_id')
      .notNull()
      .references(() => tables.id),
    seatSessionId: text('seat_session_id').references(() => seatSessions.id),
    playerId: text('player_id').references(() => players.id),
    kind: text('kind', { enum: MOVEMENT_KINDS }).notNull(),
    amount: chips('amount').notNull(),
    stackBefore: chips('stack_before'),
    stackAfter: chips('stack_after'),
    /** Null when the system moved the chips (tournament payouts, rake). */
    actorPlayerId: text('actor_player_id').references(() => players.id),
    handNumber: integer('hand_number'),
    createdAt: at('created_at').notNull().defaultNow(),
  },
  (t) => [
    index('chip_movements_table_idx').on(t.tableId, t.seq),
    index('chip_movements_player_idx').on(t.playerId),
    check('chip_movements_kind_check', sql`${t.kind} in (${oneOf(MOVEMENT_KINDS)})`),
    check(
      'chip_movements_player_check',
      sql`${t.kind} = 'rake'
        or (${t.playerId} is not null and ${t.stackBefore} is not null and ${t.stackAfter} is not null)`,
    ),
    check(
      'chip_movements_stack_check',
      sql`(${t.stackBefore} is null and ${t.stackAfter} is null)
        or (${t.stackBefore} is not null and ${t.stackAfter} is not null
          and ${t.stackBefore} >= 0 and ${t.stackAfter} >= 0 and ${t.stackAfter} = ${t.stackBefore} + ${t.amount})`,
    ),
  ],
);

// ---------------------------------------------------------------- hands

/** Finished (or abandoned) hands, with the unfiltered event log. Filter before sending to clients. */
export const hands = pgTable(
  'hands',
  {
    /** Hard to guess: the id alone is enough to open a shared hand. */
    id: text('id').primaryKey(),
    tableId: text('table_id')
      .notNull()
      .references(() => tables.id),
    number: integer('number').notNull(),
    gameId: text('game_id').notNull(),
    startedAt: at('started_at').notNull(),
    endedAt: at('ended_at'),
    header: jsonb('header').$type<unknown>().notNull(),
    events: jsonb('events').$type<unknown[]>().notNull(),
    results: jsonb('results').$type<unknown>(),
  },
  (t) => [uniqueIndex('hands_table_number_idx').on(t.tableId, t.number)],
);

// ---------------------------------------------------------------- tournaments

/** Tournament director state, saved after every change; its tables live in `tables` with tournament_id set. */
export const tournaments = pgTable(
  'tournaments',
  {
    id: text('id').primaryKey(),
    hostPlayerId: text('host_player_id')
      .notNull()
      .references(() => players.id),
    status: text('status', { enum: TOURNAMENT_STATUSES }).notNull(),
    /** The director's state (plain JSON with its own version field). */
    state: jsonb('state').$type<unknown>().notNull(),
    /** The next event in a series, or the next Sit & Go, once created. */
    nextId: text('next_id'),
    createdAt: at('created_at').notNull().defaultNow(),
    updatedAt: at('updated_at').notNull().defaultNow(),
  },
  (t) => [
    index('tournaments_status_idx').on(t.status),
    check('tournaments_status_check', sql`${t.status} in (${oneOf(TOURNAMENT_STATUSES)})`),
  ],
);

/** A tournament lobby's chat and public event log, oldest first by `n`. */
export const tournamentLog = pgTable(
  'tournament_log',
  {
    n: bigserial('n', { mode: 'number' }).primaryKey(),
    tournamentId: text('tournament_id')
      .notNull()
      .references(() => tournaments.id, { onDelete: 'cascade' }),
    /** The item's id as browsers know it. */
    itemId: text('item_id').notNull(),
    at: at('at').notNull(),
    /** A LobbyItem from @rsdp/tournament, without its id and time. */
    item: jsonb('item').$type<unknown>().notNull(),
  },
  (t) => [index('tournament_log_tournament_idx').on(t.tournamentId, t.n)],
);

// ---------------------------------------------------------------- jobs

/**
 * Durable timers. A dedupe key names one logical timer: scheduling it again
 * re-arms the same row. locked_by fences a claim so a stale worker cannot
 * finish a job someone else re-claimed.
 */
export const jobs = pgTable(
  'jobs',
  {
    id: text('id').primaryKey(),
    kind: text('kind').notNull(),
    runAt: at('run_at').notNull(),
    /** Null when the job was scheduled without one. */
    payload: jsonb('payload').$type<unknown>(),
    status: text('status', { enum: JOB_STATUSES }).notNull().default('pending'),
    attempts: integer('attempts').notNull().default(0),
    lastError: text('last_error'),
    lockedUntil: at('locked_until'),
    lockedBy: text('locked_by'),
    dedupeKey: text('dedupe_key'),
    createdAt: at('created_at').notNull().defaultNow(),
  },
  (t) => [
    uniqueIndex('jobs_dedupe_key_idx').on(t.dedupeKey),
    index('jobs_status_run_at_idx').on(t.status, t.runAt),
    check('jobs_status_check', sql`${t.status} in (${oneOf(JOB_STATUSES)})`),
  ],
);

// ---------------------------------------------------------------- player notes

export const NOTE_COLORS = ['none', 'red', 'orange', 'yellow', 'green', 'blue', 'purple'] as const;
export type NoteColor = (typeof NOTE_COLORS)[number];

/** Private notes one player keeps on another, with a colour tag. Only the owner ever reads them. */
export const playerNotes = pgTable(
  'player_notes',
  {
    ownerPlayerId: text('owner_player_id')
      .notNull()
      .references(() => players.id, { onDelete: 'cascade' }),
    targetPlayerId: text('target_player_id').notNull(),
    text: text('text').notNull().default(''),
    color: text('color').notNull().default('none'),
    updatedAt: at('updated_at').notNull().defaultNow(),
  },
  (t) => [
    primaryKey({ columns: [t.ownerPlayerId, t.targetPlayerId] }),
    check('player_notes_color_check', sql`${t.color} in (${oneOf(NOTE_COLORS)})`),
  ],
);

// ---------------------------------------------------------------- avatars

export const AVATAR_KINDS = ['library', 'upload'] as const;
export type AvatarKind = (typeof AVATAR_KINDS)[number];

/** Each player's picture: a library id, or an uploaded image kept as a small data: URL. */
export const playerAvatars = pgTable(
  'player_avatars',
  {
    playerId: text('player_id')
      .primaryKey()
      .references(() => players.id, { onDelete: 'cascade' }),
    kind: text('kind').notNull(),
    value: text('value').notNull(),
    updatedAt: at('updated_at').notNull().defaultNow(),
  },
  (t) => [check('player_avatars_kind_check', sql`${t.kind} in (${oneOf(AVATAR_KINDS)})`)],
);

// ---------------------------------------------------------------- shared hands

/** A finished hand frozen as one player saw it, for a link anyone can open. Deleting the row stops the link. */
export const sharedHands = pgTable(
  'shared_hands',
  {
    id: text('id').primaryKey(),
    tableId: text('table_id').notNull(),
    handNumber: integer('hand_number').notNull(),
    createdBy: text('created_by')
      .notNull()
      .references(() => players.id, { onDelete: 'cascade' }),
    /** Table name, cents mode, seat count and the hand as the sharer saw it (a HandRecordView). */
    snapshot: jsonb('snapshot').notNull(),
    createdAt: at('created_at').notNull().defaultNow(),
  },
  (t) => [index('shared_hands_created_by_idx').on(t.createdBy)],
);

// ---------------------------------------------------------------- roadmap suggestions

export const SUGGESTION_STATUSES = ['new', 'approved', 'planned', 'in_progress', 'shipped', 'declined'] as const;

/** An idea anyone sent from the roadmap page. Only the admin changes its status. */
export const suggestions = pgTable(
  'suggestions',
  {
    id: bigserial('id', { mode: 'number' }).primaryKey(),
    /** Who to credit, as they typed it. */
    name: text('name').notNull(),
    title: text('title').notNull(),
    detail: text('detail').notNull().default(''),
    status: text('status').notNull().default('new'),
    /** The admin's short public reply, e.g. why it was declined. */
    reply: text('reply').notNull().default(''),
    createdAt: at('created_at').notNull().defaultNow(),
    updatedAt: at('updated_at').notNull().defaultNow(),
  },
  (t) => [check('suggestions_status_check', sql`${t.status} in (${oneOf(SUGGESTION_STATUSES)})`), index('suggestions_status_idx').on(t.status)],
);
